def nawiasy_poprawne(tekst):
    pary = {')': '(', ']': '[', '}': '{'}
    stos = []
    for znak in tekst:
        if znak in '([{':
            stos.append(znak)
        elif znak in pary:
            if not stos or stos.pop() != pary[znak]:
                return False
    return not stos     # coś zostało niedomknięte?
